# State-machine SHAPE guard. The trigger prevents accidental or ordinary direct status
# mutations that violate the payment state machine (only the documented transitions; success
# is immutable; backwards moves are rejected) and, with the CHECK constraints, keeps success
# rows complete (verified_at, provider_transaction_id, subscription). It does NOT prove that
# a provider verification happened: provider authenticity is established only by the
# server-side gateway verification service (payments.services.apply_verification), which
# alone may perform failed|cancelled → success (late-success recovery). Privileged direct
# database access is outside the application's trust boundary.
GUARD_STATUS_SQL = """
CREATE FUNCTION payments_payment_guard_status() RETURNS trigger AS $$
BEGIN
    IF NEW.status = OLD.status THEN
        RETURN NEW;
    END IF;
    IF (OLD.status = 'initiated' AND NEW.status IN ('pending', 'failed'))
        OR (OLD.status = 'pending' AND NEW.status IN ('success', 'failed', 'cancelled'))
        OR (OLD.status IN ('failed', 'cancelled') AND NEW.status = 'success') THEN
        RETURN NEW;
    END IF;
    RAISE EXCEPTION 'illegal payment status change % -> %', OLD.status, NEW.status
        USING ERRCODE = 'insufficient_privilege';
END;
$$ LANGUAGE plpgsql;

CREATE TRIGGER payments_payment_status_guard
    BEFORE UPDATE OF status ON payments_payment
    FOR EACH ROW EXECUTE FUNCTION payments_payment_guard_status();
"""

